{
  "decision-returnable-crate-lifetime-cost": "WITH pooled AS (SELECT a.design_code, SUM((a.buy_cents - COALESCE(a.recovery_cents, 0)) + a.repair_cents) AS net_cost_cents, SUM(a.turns) AS completed_turns, p.source_id FROM crate_assets AS a JOIN retirement_policy AS p ON a.asset_state = p.scope_state GROUP BY a.design_code, p.source_id HAVING SUM(a.turns) > 0) SELECT design_code, net_cost_cents, completed_turns, net_cost_cents / completed_turns + CASE WHEN net_cost_cents % completed_turns >= completed_turns - (net_cost_cents % completed_turns) THEN 1 ELSE 0 END AS cents_per_turn, source_id FROM pooled ORDER BY design_code COLLATE BINARY ASC",
  "decision-reverse-bundle-credit-allocations": "WITH rejected AS (SELECT DISTINCT bundle_key, unit_no FROM unit_audit) SELECT b.bundle_key, COUNT(*) AS reversed_units, -SUM(b.credit_cents / b.unit_count + CASE WHEN r.unit_no <= b.credit_cents % b.unit_count THEN 1 ELSE 0 END) AS reversal_cents FROM bundle_book AS b JOIN rejected AS r ON r.bundle_key = b.bundle_key AND r.unit_no BETWEEN 1 AND b.posted_units GROUP BY b.bundle_key ORDER BY b.bundle_key ASC",
  "decision-rotating-closed-bay-allocation": "WITH RECURSIVE teams(idx, team) AS (VALUES (0, 'A'), (1, 'B'), (2, 'C')), choices AS (SELECT s.slot_no, f.idx AS first_idx, MIN((t.idx - f.idx + 3) % 3) AS steps FROM bay_slot AS s CROSS JOIN teams AS f LEFT JOIN reservation AS r ON r.slot_no = s.slot_no AND r.load_cm <= s.door_cm LEFT JOIN teams AS t ON t.team = r.team GROUP BY s.slot_no, f.idx), allocation(slot_no, winner_idx, next_idx) AS (VALUES (0, NULL, 0) UNION ALL SELECT c.slot_no, (c.first_idx + c.steps) % 3, COALESCE((c.first_idx + c.steps + 1) % 3, c.first_idx) FROM allocation AS a JOIN choices AS c ON c.slot_no = a.slot_no + 1 AND c.first_idx = a.next_idx) SELECT a.slot_no, t.team AS awarded_team FROM allocation AS a LEFT JOIN teams AS t ON t.idx = a.winner_idx WHERE a.slot_no > 0 ORDER BY a.slot_no ASC",
  "decision-rotation-restore-exceptions": "SELECT s.roll_id, s.required_bytes, COUNT(c.roll_id) AS inspected_copies FROM sealed_roll AS s LEFT JOIN copy_check AS c ON c.roll_id = s.roll_id GROUP BY s.roll_id, s.required_bytes, s.content_tag HAVING MAX(CASE WHEN c.seen_bytes = s.required_bytes AND c.seen_tag COLLATE BINARY = s.content_tag THEN 1 ELSE 0 END) = 0 ORDER BY s.required_bytes DESC, s.roll_id ASC"
}
